// Prepare and validate POS Bill Payload from Fashion Feet Mobile POS
const body = $input.first().json.body || $input.first().json;

const phone = String(body.customer_phone || '').replace(/\D/g, '');
const invoiceNo = body.display_invoice || body.invoice_no || 'INV';
const message = body.whatsapp_message || 'Thank you for shopping at Fashion Feet!';
const branch = body.branch_name || 'Fashion Feet';
const total = body.total || 0;
const receiptUrl = body.receipt_url || '';

return [{
  json: {
    customer_phone: phone,
    invoice_no: invoiceNo,
    branch_name: branch,
    total_amount: total,
    message_text: message,
    receipt_url: receiptUrl,
    raw_payload: body
  }
}];
